1	// Package snapshot implements a persistent key-value store whose readers
2	// operate on immutable point-in-time snapshots. A snapshot never observes a
3	// write committed after it was acquired, and it keeps serving its fixed view
4	// even after the store that produced it has been closed.
5	package snapshot
6	
7	import (
8		"errors"
9		"io/fs"
10		"os"
11		"sync"
12		"sync/atomic"
13	)
14	
15	// viewFlattenLimit bounds how deep an overlay chain a published view grows
16	// before the next commit builds it on a flattened copy. Without a bound the
17	// chain would gain one map per commit for the life of the store and memory
18	// would track cumulative commits; flattening every viewFlattenLimit commits
19	// keeps live depth (and the work a read or checkpoint walk does) independent
20	// of commit count, while the flattened copies stay immutable for every
21	// snapshot already holding an older view.
22	const viewFlattenLimit = 64
23	
24	// node is one immutable version in a key's history. Versions form a linked
25	// list from newest to oldest; a snapshot pins the head current when it was
26	// acquired, so overwritten and deleted values stay readable through every
27	// view that references them. seq is the version's commit number, unique and
28	// strictly increasing along each key's chain; it orders versions across the
29	// independent chains that meet again during a pinning compaction.
30	type node struct {
31		value   []byte
32		present bool   // false marks a delete; a present nil/empty value is still a hit
33		seq     uint64 // commit order, 1-based
34		older   *node
35	}
36	
37	// view is an immutable map of keys to their newest version. Rather than
38	// copying the whole map for every commit, a view is a thin overlay: its own
39	// keys on top of a base view it never modifies. Reads descend the short chain
40	// of overlays; the current view, snapshots and cursors simply point at one.
41	//
42	// A view's keys map may itself hold the whole keyspace: the base layer
43	// (base == nil) used by recovery, compaction and periodic flattening. Maps
44	// are never mutated after publication, so reading them needs no lock; only
45	// the commit path, which has just created a fresh overlay, writes its keys.
46	type view struct {
47		keys  map[string]*node
48		base  *view
49		depth int // number of overlays from this view to its flat base
50	}
51	
52	// newView returns an empty overlay atop base (nil for a flat base view).
53	func newView(base *view) *view {
54		d := 1
55		if base != nil {
56			d = base.depth + 1
57		}
58		return &view{keys: make(map[string]*node), base: base, depth: d}
59	}
60	
61	// lookup returns the newest version recorded for key anywhere along the
62	// overlay chain, or nil when the key was never written.
63	func (v *view) lookup(key string) *node {
64		for cur := v; cur != nil; cur = cur.base {
65			if n, ok := cur.keys[key]; ok {
66				return n
67			}
68		}
69		return nil
70	}
71	
72	// rangeEach visits the terminal version of every distinct key, fn once per
73	// key, walking newest-to-oldest so an overlay entry shadows its base.
74	func (v *view) rangeEach(fn func(key string, n *node) bool) {
75		seen := make(map[string]struct{})
76		for cur := v; cur != nil; cur = cur.base {
77			for k, n := range cur.keys {
78				if _, ok := seen[k]; ok {
79					continue
80				}
81				seen[k] = struct{}{}
82				if !fn(k, n) {
83					return
84				}
85			}
86		}
87	}
88	
89	// flatten materializes one flat map holding the view's complete terminal
90	// state. It allocates a fresh map and shares only immutable nodes, so views
91	// already published stay untouched.
92	func (v *view) flatten() *view {
93		flat := newView(nil)
94		v.rangeEach(func(k string, n *node) bool {
95			flat.keys[k] = n
96			return true
97		})
98		return flat
99	}
100	
101	// Store is an open key-value store backed by a directory on disk.
102	type Store struct {
103		mu sync.Mutex // serializes writers and guards the fields below
104	
105		dir       string
106		wal       *walWriter
107		current   atomic.Pointer[view] // latest committed view; lock-free for readers
108		snapshots atomic.Uint64        // cumulative number of snapshots handed out
109		nextSeq   uint64               // highest commit sequence handed out; guarded by mu
110	
111		// chain is the in-memory record of the usable checkpoint layers paired
112		// with the current WAL, oldest first. Empty means no checkpoint is live
113		// (the next Checkpoint writes a base). Compaction re-anchors it against
114		// the replacement log; Checkpoint appends a delta and prunes the window.
115		chain []layerState
116		// dirty keys were touched by effective commits strictly after the newest
117		// layer in chain; they are exactly the keys the next delta layer covers.
118		// nil until the first such commit.
119		dirty []string
120		// legacyLive reports that a version-1 single-file snapshot.ckpt was the
121		// checkpoint paired with the WAL at open and has not been replaced by a
122		// layered chain or retired by compaction. Compaction must durably retire
123		// it before swapping the WAL, exactly as it retires a layered chain.
124		legacyLive bool
125	
126		// Open cursors pin their fixed view's versions against compaction. The
127		// set is read by Compact (which holds mu) and mutated at cursor
128		// open/close, using cursorMu; reads never take either lock.
129		cursorMu sync.Mutex
130		cursors  map[*Cursor]struct{}
131	
132		// Group-commit queue. Every state-changing commit (single Put/Delete just
133		// like CommitBatch) that arrives while another commit is forcing the log
134		// lines up here; one leader drains the queue, encodes the waiting commits
135		// and shares a single flush plus fsync across them.
136		// queueMu only ever guards this queue and committer; it is never held
137		// across disk I/O, so readers and enqueuers never wait on a sync.
138		queueMu   sync.Mutex
139		queue     []*pendingBatch
140		committer bool
141	
142		// Test hook, nil outside tests. leaderHook runs once after a commit has
143		// become leader, before its first queue drain, and lets tests hold a
144		// leader until a known number of commits have coalesced.
145		leaderHook func()
146	
147		closed atomic.Bool
148	}
149	
150	// Snapshot is a stable read-only view of a store captured at one instant. It
151	// owns no store resources of its own and stays usable after the store has
152	// been closed; a cursor opened from it does register with the store while it
153	// pins versions.
154	type Snapshot struct {
155		v     atomic.Pointer[view] // nil once the snapshot is closed
156		store *Store               // back-reference for cursor pin accounting
157	}
158	
159	// Open opens or creates a persistent store in dir. A path that names a
160	// regular file rather than a directory returns an error wrapping
161	// fs.ErrInvalid.
162	func Open(dir string) (*Store, error) {
163		info, err := os.Stat(dir)
164		if err == nil {
165			if !info.IsDir() {
166				return nil, errNotDir
167			}
168		} else {
169			if !errors.Is(err, fs.ErrNotExist) {
170				return nil, err
171			}
172			if err := os.MkdirAll(dir, 0o700); err != nil {
173				return nil, err
174			}
175		}
176	
177		// A replacement log from a compaction killed before its rename can never
178		// be complete state of record; the old wal.log is. Drop the stale file.
179		// Likewise, staging debris from a kill mid-checkpoint (a half-built layer
180		// temp or a legacy single-file temp) is swept: only finished layers are
181		// ever read.
182		if err := removeStaleCompact(dir); err != nil {
183			return nil, err
184		}
185		if err := sweepCheckpointDebris(dir); err != nil {
186			return nil, err
187		}
188		if err := sweepStagedChain(dir); err != nil {
189			return nil, err
190		}
191	
192		latest := newView(nil)
193		var replaySeq uint64
194		var snapshotCount uint64
195		var validSize int64
196		var chain []layerState
197		var tailTouched []string
198		var legacyLive bool
199	
200		// apply installs one replayed record into the latest view. Legacy
201		// records (written before sequence numbers existed) carry no seq; replay
202		// order is commit order, so number them sequentially.
203		apply := func(op byte, key string, value []byte, seq uint64) {
204			if seq == 0 {
205				replaySeq++
206				seq = replaySeq
207			} else if seq > replaySeq {
208				replaySeq = seq
209			}
210			switch op {
211			case opPut, opPutSeq:
212				latest.keys[key] = &node{value: cloneBytes(value), present: true, seq: seq, older: latest.keys[key]}
213			case opDelete, opDeleteSeq:
214				latest.keys[key] = &node{present: false, seq: seq, older: latest.keys[key]}
215			}
216		}
217	
218		// Fast reopen: seed memory from the longest valid checkpoint-chain prefix
219		// and replay only the WAL written after its last layer. A layer is
220		// accepted only as a whole and only when it links to the layer before; a
221		// missing, truncated, checksum-bad, unknown-version or unlinked layer
222		// rejects it and every layer after it, and recovery falls back to the
223		// previous layer, to the legacy single-file checkpoint, or finally to a
224		// from-scratch WAL replay.
225		chainInfo, chainErr := readChain(dir)
226		if chainErr != nil {
227			return nil, chainErr
228		}
229		// Reject the suffix outright: anything beyond the longest intact, linked
230		// prefix is removed as a whole so a broken layer never pairs with the WAL
231		// and never occupies space. Half a layer is never installed.
232		pruneRejectedChainFiles(dir, len(chainInfo.layers))
233		walLen, sizeErr := walFileSize(dir)
234		if sizeErr != nil {
235			return nil, sizeErr
236		}
237		// The selected layer's cut must lie inside this exact WAL. Cuts are
238		// nondecreasing along the chain, so any suffix whose cut ran past the end
239		// of the file is rejected as a whole down to the last pairable layer.
240		for len(chainInfo.layers) > 0 && chainInfo.layers[len(chainInfo.layers)-1].offset > walLen {
241			removeRejectedChainSuffix(dir, chainInfo.layers[len(chainInfo.layers)-1].index)
242			chainInfo.layers = chainInfo.layers[:len(chainInfo.layers)-1]
243		}
244	
245		switch {
246		case len(chainInfo.layers) > 0:
247			// Compose the valid prefix: each layer overrides the one it builds on.
248			var last layerState
249			for _, l := range chainInfo.layers {
250				for _, e := range l.entries {
251					latest.keys[e.key] = &node{value: cloneBytes(e.value), present: e.present, seq: e.seq}
252				}
253				last = l
254			}
255			chain = chainInfo.layers
256			replaySeq = last.seq
257			// Replay the tail, remembering touched keys so the first delta layer
258			// taken in this opening also covers commits already past the cut.
259			tailApply := func(op byte, key string, value []byte, seq uint64) {
260				if op == opPut || op == opPutSeq || op == opDelete || op == opDeleteSeq {
261					tailTouched = append(tailTouched, key)
262				}
263				apply(op, key, value, seq)
264			}
265			var rerr error
266			validSize, snapshotCount, rerr = replayWALTail(dir, last.offset, last.snaps, tailApply)
267			if rerr != nil {
268				return nil, rerr
269			}
270		default:
271			// No layered chain: accept a legacy version-1 checkpoint if one is
272			// intact and pairs with this WAL, otherwise replay the whole log.
273			cp, cpOK, cpErr := loadLegacyCheckpoint(dir)
274			if cpErr != nil {
275				removeRejectedLegacy(dir)
276				cpOK = false
277			}
278			if cpOK && (cp.offset < 0 || cp.offset > walLen) {
279				removeRejectedLegacy(dir)
280				cpOK = false
281			}
282			if cpOK {
283				legacyLive = true
284				for _, e := range cp.entries {
285					latest.keys[e.key] = &node{value: cloneBytes(e.value), present: e.present, seq: e.seq}
286				}
287				replaySeq = cp.seq
288				validSize, snapshotCount, err = replayWALTail(dir, cp.offset, cp.snaps, apply)
289				if err != nil {
290					return nil, err
291				}
292			} else {
293				validSize, snapshotCount, err = replayWAL(dir, apply)
294				if err != nil {
295					return nil, err
296				}
297			}
298		}
299	
300		wal, err := openWALWriter(dir, validSize)
301		if err != nil {
302			return nil, err
303		}
304	
305		s := &Store{
306			dir:        dir,
307			wal:        wal,
308			cursors:    make(map[*Cursor]struct{}),
309			nextSeq:    replaySeq,
310			chain:      chain,
311			dirty:      dedupeKeys(nil, tailTouched),
312			legacyLive: legacyLive,
313		}
314		s.snapshots.Store(snapshotCount)
315		s.current.Store(latest)
316		return s, nil
317	}
318	
319	// dedupeKeys returns app's distinct keys appended to dst, first occurrence
320	// wins, preserving order.
321	func dedupeKeys(dst, src []string) []string {
322		seen := make(map[string]struct{}, len(src))
323		out := dst
324		for _, k := range src {
325			if _, ok := seen[k]; ok {
326				continue
327			}
328			seen[k] = struct{}{}
329			out = append(out, k)
330		}
331		return out
332	}
333	
334	// Put stores value under key. An empty key returns an error wrapping
335	// fs.ErrInvalid. A nil or empty value is stored as-is: a following Get on the
336	// key reports a hit. The store does not keep a reference to value.
337	//
338	// Put is exactly a one-op batch: it joins the same group-commit queue as
339	// CommitBatch, so a single write and concurrent batches can share one disk
340	// sync while each keeps its own crash atomicity.
341	func (s *Store) Put(key string, value []byte) error {
342		if s.closed.Load() {
343			return errStoreClosed
344		}
345		if key == "" {
346			return errEmptyKey
347		}
348		return s.commit([]BatchOp{{Key: key, Value: value}})
349	}
350	
351	// Delete removes key. Deleting an empty key returns an error wrapping
352	// fs.ErrInvalid; deleting a key that was never written or is already deleted
353	// is not an error and commits nothing. It joins the same group-commit queue a
354	// batch uses.
355	func (s *Store) Delete(key string) error {
356		if s.closed.Load() {
357			return errStoreClosed
358		}
359		if key == "" {
360			return errEmptyKey
361		}
362		return s.commit([]BatchOp{{Key: key, Delete: true}})
363	}
364	
365	type pendingBatch struct {
366		ops  []BatchOp
367		done chan error // buffered(1); the leader delivers the commit result
368	}
369	
370	// commitPlan is one queued batch resolved against the cumulative state built
371	// up across its whole sync group.
372	type commitPlan struct {
373		view  *view // cumulative view after this batch; nil when it committed nothing
374		dirty []string
375	}
376	
377	// BatchOp is one change in a batch committed with CommitBatch. Delete false
378	// stores Value under Key (a nil or empty Value is still a hit); Delete true
379	// removes Key.
380	type BatchOp struct {
381		Key    string
382		Value  []byte
383		Delete bool
384	}
385	
386	// commit enqueues ops as one atomic framed commit and drives the leader loop.
387	// Single-key Put/Delete and CommitBatch are all this one path.
388	func (s *Store) commit(ops []BatchOp) error {
389		if s.closed.Load() {
390			return errStoreClosed
391		}
392		if err := validateBatchOps(ops); err != nil {
393			return err
394		}
395	
396		me := &pendingBatch{ops: ops, done: make(chan error, 1)}
397	
398		// Enqueue. queueMu guards only the queue and the leader flag and is
399		// never held across disk I/O, so followers can join a group while the
400		// leader is syncing and readers never wait.
401		s.queueMu.Lock()
402		if s.closed.Load() {
403			s.queueMu.Unlock()
404			return errStoreClosed
405		}
406		s.queue = append(s.queue, me)
407		if s.committer {
408			s.queueMu.Unlock()
409			return <-me.done // the running leader will drain this batch
410		}
411		s.committer = true
412		s.queueMu.Unlock()
413	
414		// Test-only rendezvous: invoked once by the elected leader before its
415		// first queue drain. Production leaves it nil.
416		if s.leaderHook != nil {
417			s.leaderHook()
418		}
419	
420		// Leadership: drain groups until the queue is empty. Each group takes
421		// s.mu while it forces the log, which serializes it with Snapshot,
422		// Checkpoint, Compact and Close, so a group never straddles a log swap or
423		// a layer capture.
424		for {
425			s.queueMu.Lock()
426			// Resign and re-check the queue under one critical section, so a
427			// batch enqueuing in this instant either observes the still-active
428			// leader or becomes the next one; no batch can be left queued with
429			// no leader to drain it.
430			if len(s.queue) == 0 {
431				s.committer = false
432				s.queueMu.Unlock()
433				break
434			}
435			group := s.queue
436			s.queue = nil
437			s.queueMu.Unlock()
438			for p, rerr := range s.commitGroup(group) {
439				group[p].done <- rerr
440			}
441		}
442	
443		return <-me.done
444	}
445	
446	// CommitBatch applies a group of writes and deletes as one atomic commit:
447	// the whole batch becomes visible together or not at all, and snapshots and
448	// cursors fixed at any instant see either the state before the batch or the
449	// state after it, never an in-between mixture. Changes are applied in list
450	// order; a later change to the same key overrides an earlier one within the
451	// batch. Concurrent batches take effect in commit (enqueue) order, and a
452	// later committed batch's same-key change overrides an earlier one's.
453	//
454	// Batches committed concurrently (with single Put/Delete calls among them)
455	// share the disk sync: one leader drains the queue, encodes every waiting
456	// commit as its own recoverable framed commit and forces them all with one
457	// flush plus fsync, so N commits arriving together cost one sync while each
458	// stays whole on recovery; a commit that arrives while a sync is in flight
459	// rides the next one. Reads take none of these locks and are never blocked by
460	// the sync.
461	//
462	// If any change has an empty key the whole batch is rejected before it is
463	// queued or committed: an error wrapping fs.ErrInvalid is returned, no frame
464	// is written and the store's state is unchanged. A delete of a key that is
465	// absent or already deleted commits nothing, exactly like Delete; a batch
466	// containing only such no-ops (or an empty slice) commits nothing and
467	// returns nil. CommitBatch on a closed store returns an error wrapping
468	// fs.ErrClosed.
469	//
470	// Each batch is forced to stable storage before its call returns and is
471	// published as one new view; a process killed mid-commit therefore reopens
472	// with the entire batch present or entirely absent. The store does not keep
473	// references to the op Value slices after return.
474	func (s *Store) CommitBatch(ops []BatchOp) error {
475		return s.commit(ops)
476	}
477	
478	// validateBatchOps checks argument-only invariants before a batch is queued.
479	// Empty keys map to fs.ErrInvalid, exactly as for Put and Delete.
480	func validateBatchOps(ops []BatchOp) error {
481		for i := range ops {
482			if ops[i].Key == "" {
483				return errEmptyKey
484			}
485		}
486		for i := range ops {
487			if len(ops[i].Key) > maxRecord || (!ops[i].Delete && seqSize+len(ops[i].Value) > maxRecord) {
488				return errRecordTooLarge()
489			}
490		}
491		return nil
492	}
493	
494	func errRecordTooLarge() error { return errors.New("snapshot: record too large") }
495	
496	// commitGroup encodes and forces every queued batch with one flush and one
497	// sync, then publishes one view per effective batch in queue (commit) order.
498	// It returns one result per batch. An encoding or sync failure fails the
499	// whole group: nothing it contained is published or sequenced. The single
500	// committer calls this; s.mu is taken for the entire force, exactly as the
501	// view transitions and checkpoint watermarks need.
502	func (s *Store) commitGroup(group []*pendingBatch) []error {
503		results := make([]error, len(group))
504	
505		s.mu.Lock()
506		defer s.mu.Unlock()
507		if s.closed.Load() || s.wal == nil {
508			// Close ran between the drain and the lock; nothing can commit.
509			for i := range results {
510				results[i] = errStoreClosed
511			}
512			return results
513		}
514	
515		// Remember where the group starts so any failure can rewind the log:
516		// unacknowledged frames must not linger at EOF and reappear under a
517		// later commit or after a reopen. Nothing is buffered here (the previous
518		// group always flushed), so EOF is the exact offset.
519		groupStart, posErr := s.wal.position()
520		if posErr != nil {
521			for i := range results {
522				results[i] = posErr
523			}
524			return results
525		}
526		rollback := func(cause error) []error {
527			if err := s.wal.truncateTo(groupStart); err != nil {
528				cause = errors.Join(cause, err)
529			}
530			for i := range results {
531				results[i] = cause
532			}
533			return results
534		}
535	
536		base := s.current.Load()
537		seq := s.nextSeq
538		plans := make([]commitPlan, 0, len(group))
539		encodedAny := false
540		var groupDirty []string
541	
542		for _, p := range group {
543			// Each batch gets its own thin immutable overlay on the previous
544			// batch's overlay, so the view it publishes is a valid point-in-time
545			// state independent of later batches, and queued batches cost memory
546			// proportional to their own ops rather than the whole live keyspace.
547			// When the chain has grown deep, flatten first so live depth stays
548			// bounded by viewFlattenLimit instead of cumulative commit count.
549			if base.depth >= viewFlattenLimit {
550				base = base.flatten()
551			}
552			v := newView(base)
553			var changes []batchChange
554			for i := range p.ops {
555				op := &p.ops[i]
556				head := v.lookup(op.Key)
557				if op.Delete {
558					if head == nil || !head.present {
559						continue // idempotent no-op, matching the single Delete
560					}
561					seq++
562					changes = append(changes, batchChange{key: op.Key, seq: seq, delete: true})
563					v.keys[op.Key] = &node{present: false, seq: seq, older: head}
564				} else {
565					seq++
566					value := cloneBytes(op.Value)
567					changes = append(changes, batchChange{key: op.Key, seq: seq, value: value})
568					v.keys[op.Key] = &node{value: value, present: true, seq: seq, older: head}
569				}
570			}
571			if len(changes) > 0 {
572				if err := s.wal.encodeBatch(changes); err != nil {
573					return rollback(err)
574				}
575				encodedAny = true
576				for i := range changes {
577					groupDirty = append(groupDirty, changes[i].key)
578				}
579			}
580			var planView *view
581			if len(changes) > 0 {
582				planView = v
583			}
584			plans = append(plans, commitPlan{view: planView})
585			base = v
586		}
587	
588		if encodedAny {
589			// One flush, one fsync for the whole group. Return means every
590			// encoded batch in it is durable as a self-contained framed commit.
591			if err := s.wal.flushSync(); err != nil {
592				return rollback(err)
593			}
594		}
595	
596		s.nextSeq = seq
597		for _, plan := range plans {
598			if plan.view != nil {
599				s.current.Store(plan.view)
600			}
601		}
602		s.dirty = dedupeKeys(s.dirty, groupDirty)
603		return results
604	}
605	
606	// Get returns the latest committed value for key. Empty keys, keys never
607	// written and deleted keys are all misses: ok is false and err is nil. The
608	// returned bytes are owned by the caller.
609	func (s *Store) Get(key string) ([]byte, bool, error) {
610		if s.closed.Load() {
611			return nil, false, errStoreClosed
612		}
613		if key == "" {
614			return nil, false, nil
615		}
616		val, ok := lookupView(s.current.Load(), key)
617		return val, ok, nil
618	}
619	
620	// Compact reclaims history: values that were overwritten or deleted and are
621	// not needed by any open snapshot or cursor are dropped from memory and the
622	// write-ahead log is atomically rewritten, so the directory occupies less
623	// space than before whenever reclaimable history existed.
624	//
625	// When a checkpoint chain is live, compaction keeps the generations inside
626	// the retention window and re-anchors them against the replacement log: that
627	// log is written as one segment per surviving layer (its prefix reproducing
628	// the layer's terminal state at a fresh cut), followed by the post-window
629	// changes and the snapshot-count meta, and the rebuilt layers reference those
630	// cuts. Generations outside the window are retired together with the old
631	// chain and stop occupying space immediately.
632	//
633	// Every open snapshot keeps its exact fixed view; every open cursor keeps
634	// paging through its exact fixed sequence, and the one version per key its
635	// view shows stays in the rewritten log until the cursor closes; the next
636	// compaction then reclaims it and shrinks the directory further. A process
637	// killed at any point during compaction reopens in a complete commit state,
638	// with every successful write, deletion and the cumulative snapshot count
639	// intact; no intermediate file needs a second compaction or checkpoint to
640	// repair.
641	//
642	// Compact serializes with writes, deletes, snapshots, cursor opens, closing
643	// and other compactions (the group-commit leader and every other mutator
644	// take the same lock); concurrent or repeated calls queue and all return nil.
645	// Compacting a closed store returns an error wrapping fs.ErrClosed.
646	func (s *Store) Compact() error {
647		s.mu.Lock()
648		defer s.mu.Unlock()
649		if s.closed.Load() {
650			return errStoreClosed
651		}
652	
653		cur := s.current.Load()
654	
655		// Pinned versions, keyed by commit sequence (globally unique). The
656		// current head of every live key in the latest view is retained; each
657		// open cursor additionally pins the single head version its fixed view
658		// shows for every present key in its range. A deleted key's tombstone is
659		// retained only when a cursor still reads an older value under it, so
660		// replay links that value as the tombstone's predecessor; otherwise the
661		// key is dropped from the rewritten log altogether, as before.
662		pinned := make(map[uint64]*node)
663		keySeqs := make(map[string][]uint64)
664		cursorPins := make(map[string]bool)
665		pin := func(k string, n *node) {
666			if n == nil {
667				return
668			}
669			if _, ok := pinned[n.seq]; !ok {
670				pinned[n.seq] = n
671				keySeqs[k] = append(keySeqs[k], n.seq)
672			}
673		}
674		for _, c := range s.openCursors() {
675			for _, k := range c.keys {
676				cursorPins[k] = true
677				pin(k, c.v.lookup(k)) // exactly the version this cursor pages out
678			}
679		}
680		for k, n := range keySetOf(cur) {
681			if n.present || cursorPins[k] {
682				pin(k, n) // live head, or a tombstone shielding a pinned value
683			}
684		}
685	
686		plan := buildCompactionPlan(pinned, keySeqs)
687		snapshotCount := s.snapshots.Load()
688	
689		// The surviving window, oldest first. Layers before it are retired.
690		window := checkpointWindow
691		if window > len(s.chain) {
692			window = len(s.chain)
693		}
694		first := len(s.chain) - window
695		windowLayers := s.chain[first:]
696		hadChain := len(s.chain) > 0
697		// paired reports any checkpoint — layered chain or a legacy single file —
698		// whose cut belongs to the WAL about to be replaced. It must be withdrawn
699		// before the swap so no checkpoint is ever read against a different log.
700		paired := hadChain || s.legacyLive
701	
702		// Phase 1 (nothing live is touched yet): build and sync the complete
703		// replacement log, and when layers survive, the matching staged chain.
704		// Any failure here removes the staged files and leaves the store and the
705		// old WAL/chain exactly as they were, so committing can continue.
706		var seg *segmentedWAL
707		if !hadChain {
708			if err := buildCompactWAL(s.dir, plan.histories(), snapshotCount); err != nil {
709				return err
710			}
711		} else {
712			// Full terminal state at each window layer's watermark, composed from
713			// the complete old chain (including the generations about to retire).
714			termStates := make([][]checkpointEntry, window)
715			for w := 0; w < window; w++ {
716				termStates[w] = composeLayers(s.chain[:first+w+1])
717			}
718			seg = planSegmentedWAL(plan, windowLayers, termStates, cur)
719			if err := buildSegmentedCompactArtifacts(s.dir, seg, snapshotCount); err != nil {
720				return err
721			}
722		}
723	
724		// Phase 2: the replacement must never meet a paired checkpoint on reopen.
725		// Durably withdraw the whole layered chain and/or the legacy file while
726		// the old wal.log is still in place; a crash after this but before the
727		// rename simply replays the old log in full. Failure precedes any
728		// stateful move, so drop the staged files and leave the store untouched.
729		if paired {
730			if err := retireChain(s.dir); err != nil {
731				removeStaleCompact(s.dir)
732				removeStagedChain(s.dir)
733				return err
734			}
735			s.legacyLive = false
736		}
737		oldWAL := s.wal
738		if err := oldWAL.close(); err != nil {
739			// Staged files have not become state of record; remove them and
740			// reopen a writer on the untouched old log, so no repair-only
741			// intermediate lingers and the next commit proceeds.
742			removeStaleCompact(s.dir)
743			removeStagedChain(s.dir)
744			reopened, openErr := openWALWriter(s.dir, -1)
745			if openErr != nil {
746				return err
747			}
748			s.wal = reopened
749			return err
750		}
751		// Phase 3: atomically rename the temp over wal.log, force the directory
752		// and open a writer on the new log. If the rename never landed the old
753		// log is intact and committing continues (staged chain is dropped).
754		nextWAL, renamed, installErr := installCompactWAL(s.dir)
755		if nextWAL == nil {
756			// The rename landed but the new log cannot be opened: the directory
757			// is not in a state where further commits are safe, so mark the
758			// store closed rather than leaving a handle only another compaction
759			// could repair.
760			s.closed.Store(true)
761			s.wal = nil
762			return installErr
763		}
764		s.wal = nextWAL
765		if renamed {
766			s.current.Store(plan.freshView())
767			if hadChain {
768				// dropCheckpoint clears any in-memory and on-disk chain so the
769				// next Checkpoint starts a fresh base with no O_EXCL collision.
770				dropCheckpoint := func() {
771					s.chain = nil
772					s.dirty = nil
773					os.RemoveAll(checkpointDirPath(s.dir))
774				}
775				if window == 0 {
776					dropCheckpoint()
777					removeStagedChain(s.dir)
778				} else if err := activateStagedChain(s.dir); err != nil {
779					// The new WAL is already live; rather than leave a half
780					// installed chain, run with no live checkpoint. The next
781					// Checkpoint establishes a fresh base.
782					dropCheckpoint()
783				} else {
784					info, ierr := readChain(s.dir)
785					if ierr != nil || len(info.layers) != window {
786						dropCheckpoint()
787					} else {
788						s.chain = info.layers
789						s.dirty = seg.tailKeys
790					}
791				}
792			}
793		} else if hadChain {
794			// Rename failed; the old WAL stayed. retireChain already removed the
795			// old chain, so drop the staged replacement as well: no checkpoint
796			// pairs with this WAL. Committing continues; the next Checkpoint heals.
797			removeStagedChain(s.dir)
798			s.chain = nil
799			s.dirty = nil
800		}
801		return installErr
802	}
803	
804	// keySetOf returns the distinct keys present anywhere in the view.
805	func keySetOf(v *view) map[string]*node {
806		out := make(map[string]*node)
807		v.rangeEach(func(k string, n *node) bool {
808			out[k] = n
809			return true
810		})
811		return out
812	}
813	
814	// Checkpoint appends one self-describing, checksummed layer to the checkpoint
815	// chain so the next Open seeds memory from the longest intact layer prefix
816	// and replays only the write-ahead log written after it, instead of replaying
817	// the whole log. The first layer (the base) holds complete committed state;
818	// every later layer covers only commits after the layer it builds on.
819	// Checkpoint changes nothing visible: every committed write and deletion, the
820	// cumulative snapshot count and every open snapshot or cursor are unaffected,
821	// and reads keep hitting memory without touching disk.
822	//
823	// Producing a layer and making it live are two distinct steps: the layer is
824	// captured under the write lock, built fully under a temporary name and
825	// forced to stable storage, then atomically renamed into place and linked to
826	// the previous layer by a content hash. A kill at any instant leaves either
827	// the old complete chain or the chain extended by one complete layer; reopen
828	// observes one complete committed state, never a half layer (staging debris
829	// is swept on the next open).
830	//
831	// Only checkpointWindow newest generations are kept: appending past the
832	// window rebuilds the chain with the oldest surviving layer as a fresh full
833	// base against the unchanged WAL and deletes the retired layers immediately.
834	//
835	// Checkpoint serializes with writes, batch commits, snapshots, cursor opens,
836	// compaction and closing (it takes the same write lock), but never with
837	// lock-free reads: Get, scans, snapshot reads and cursor paging proceed while
838	// it runs. A batch stays wholly on one side of the captured cut, and history
839	// pinned by open snapshots or cursors is left untouched. On a closed store
840	// Checkpoint returns an error wrapping fs.ErrClosed.
841	func (s *Store) Checkpoint() error {
842		s.mu.Lock()
843		defer s.mu.Unlock()
844		if s.closed.Load() {
845			return errStoreClosed
846		}
847	
848		offset, err := s.wal.position()
849		if err != nil {
850			return err
851		}
852		cur := s.current.Load()
853		snaps := s.snapshots.Load()
854	
855		if len(s.chain) == 0 {
856			// First layer: full base state. This also upgrades a legacy
857			// single-file directory: the old file is removed once the base is
858			// staged, and the WAL it pairs with has not changed.
859			layer := capturedLayer{
860				index:   0,
861				entries: captureView(cur),
862				offset:  uint64(offset),
863				seq:     s.nextSeq,
864				snaps:   snaps,
865			}
866			if err := installLayer(s.dir, layer); err != nil {
867				return err
868			}
869			if err := removeLegacyCheckpoint(s.dir); err != nil {
870				return err
871			}
872			s.legacyLive = false
873		} else {
874			last := s.chain[len(s.chain)-1]
875			layer := capturedLayer{
876				index:   last.index + 1,
877				prevCRC: last.crc,
878				entries: captureDelta(cur, s.dirty),
879				offset:  uint64(offset),
880				seq:     s.nextSeq,
881				snaps:   snaps,
882			}
883			if err := installLayer(s.dir, layer); err != nil {
884				return err
885			}
886		}
887	
888		info, err := readChain(s.dir)
889		if err != nil {
890			return err
891		}
892		s.chain = info.layers
893		s.dirty = nil
894	
895		// Enforce the retention window: keep only the newest checkpointWindow
896		// layers, rebuilt as a standalone chain against the same unchanged WAL.
897		if len(s.chain) > checkpointWindow {
898			if err := s.rebaseChainToWindow(); err != nil {
899				return err
900			}
901		}
902		return nil
903	}
904	
905	// rebaseChainToWindow rebuilds the live chain so only the newest
906	// checkpointWindow layers remain: the oldest kept layer becomes a fresh full
907	// base (materialized from the complete in-memory chain) at its existing WAL
908	// cut, and the layers after it keep their delta content at their existing
909	// cuts. The WAL is not touched.
910	func (s *Store) rebaseChainToWindow() error {
911		keep := checkpointWindow
912		if keep > len(s.chain) {
913			keep = len(s.chain)
914		}
915		first := len(s.chain) - keep
916		// Materialize full terminal state at the oldest kept layer.
917		full := composeLayers(s.chain[:first+1])
918		newLayers := make([]capturedLayer, 0, keep)
919		newLayers = append(newLayers, capturedLayer{
920			index: 0, entries: full,
921			offset: uint64(s.chain[first].offset),
922			seq:    s.chain[first].seq,
923			snaps:  s.chain[first].snaps,
924		})
925		for j := first + 1; j < len(s.chain); j++ {
926			newLayers = append(newLayers, capturedLayer{
927				index:   uint32(j - first),
928				entries: s.chain[j].entries,
929				offset:  uint64(s.chain[j].offset),
930				seq:     s.chain[j].seq,
931				snaps:   s.chain[j].snaps,
932			})
933		}
934		if err := replaceCheckpointChain(s.dir, newLayers); err != nil {
935			return err
936		}
937		info, err := readChain(s.dir)
938		if err != nil {
939			return err
940		}
941		s.chain = info.layers
942		return nil
943	}
944	
945	// composeLayers returns the full terminal state after applying layers in
946	// order (each overriding the one before), sorted by key for a canonical base.
947	func composeLayers(layers []layerState) []checkpointEntry {
948		term := make(map[string]checkpointEntry)
949		for _, l := range layers {
950			for _, e := range l.entries {
951				term[e.key] = e // later layer wins; tombstones survive as tombstones
952			}
953		}
954		out := make([]checkpointEntry, 0, len(term))
955		for _, e := range term {
956			out = append(out, e)
957		}
958		sortEntries(out)
959		return out
960	}
961	
962	// openCursors snapshots the set of currently open cursors. Cursor views and
963	// bounds are immutable after opening, so reading their fields here needs no
964	// per-cursor lock.
965	func (s *Store) openCursors() []*Cursor {
966		s.cursorMu.Lock()
967		defer s.cursorMu.Unlock()
968		cs := make([]*Cursor, 0, len(s.cursors))
969		for c := range s.cursors {
970			cs = append(cs, c)
971		}
972		return cs
973	}
974	
975	// Snapshot acquires a stable view. It never observes writes committed after
976	// it returns, and keeps serving that view regardless of later writes,
977	// deletes or Store.Close, until the Snapshot itself is closed.
978	func (s *Store) Snapshot() (*Snapshot, error) {
979		s.mu.Lock()
980		defer s.mu.Unlock()
981		if s.closed.Load() {
982			return nil, errStoreClosed
983		}
984		count := s.snapshots.Add(1)
985		if err := s.wal.appendMeta(count); err != nil {
986			s.snapshots.Add(^uint64(0))
987			return nil, err
988		}
989		snap := &Snapshot{store: s}
990		snap.v.Store(s.current.Load())
991		return snap, nil
992	}
993	
994	// Get reads key from the snapshot's fixed view. Old values overwritten or
995	// deleted afterwards are still readable; keys created afterwards, empty
996	// keys and keys absent or deleted when the snapshot was taken are misses. A
997	// read from a closed snapshot is also a plain miss, never an error. The
998	// returned bytes are owned by the caller.
999	func (s *Snapshot) Get(key string) ([]byte, bool) {
1000		if key == "" {
1001			return nil, false
1002		}
1003		v := s.v.Load()
1004		if v == nil {
1005			return nil, false // closed snapshot
1006		}
1007		n := v.lookup(key)
1008		if n == nil || !n.present {
1009			return nil, false
1010		}
1011		return cloneBytes(n.value), true
1012	}
1013	
1014	// Close releases the snapshot's fixed view. Closing more than once is a
1015	// no-op returning nil.
1016	func (s *Snapshot) Close() error {
1017		s.v.Store(nil)
1018		return nil
1019	}
1020	
1021	// Close flushes and closes the store. Data already committed stays complete
1022	// and readable after reopening the directory. Snapshots still open keep
1023	// serving their fixed views until closed themselves; closing an already
1024	// closed store is a no-op returning nil.
1025	func (s *Store) Close() error {
1026		s.mu.Lock()
1027		if !s.closed.CompareAndSwap(false, true) {
1028			s.mu.Unlock()
1029			return nil
1030		}
1031		wal := s.wal
1032		s.wal = nil
1033		s.mu.Unlock()
1034	
1035		return wal.close()
1036	}
1037	
1038	func lookupView(v *view, key string) ([]byte, bool) {
1039		n := v.lookup(key)
1040		if n == nil || !n.present {
1041			return nil, false
1042		}
1043		return cloneBytes(n.value), true
1044	}
1045	
1046	func cloneBytes(b []byte) []byte {
1047		if b == nil {
1048			return nil
1049		}
1050		c := make([]byte, len(b))
1051		copy(c, b)
1052		return c
1053	}
1054

