1	package snapshot
2	
3	import (
4		"bufio"
5		"encoding/binary"
6		"errors"
7		"fmt"
8		"hash/crc32"
9		"io"
10		"os"
11	)
12	
13	// On-disk write-ahead log.
14	//
15	// Every successful Put/Delete (and every successfully acquired Snapshot) is
16	// appended as one framed record and forced to stable storage before the call
17	// reports success, so reopening a directory always replays a prefix of
18	// complete records (never a half-written value) and the cumulative snapshot
19	// count is never reset.
20	//
21	// Frame layout, little-endian:
22	//
23	//	magic    uint32   recordMagic
24	//	op       byte     opPut, opDelete, opMeta, opPutSeq, opDeleteSeq,
25	//	                  opBatchBegin or opBatchEnd
26	//	keyLen   uint32
27	//	valLen   uint32
28	//	key      [keyLen]byte
29	//	value    [valLen]byte (absent for plain deletes)
30	//	crc      uint32   IEEE CRC-32 of all preceding frame bytes
31	//
32	// An opMeta record carries no key and an 8-byte little-endian value holding
33	// the cumulative number of snapshots handed out so far.
34	//
35	// The WAL is never rewritten by a checkpoint (a checkpoint only adds a side
36	// file); only compaction replaces wal.log. Compaction durably removes any
37	// live checkpoint before renaming the replacement log into place, so after a
38	// crash a checkpoint can never be found next to a WAL other than the one it
39	// was captured against: the checkpoint and the log it pairs with share a
40	// lifetime established by ordered, synced metadata operations.
41	//
42	// opPut/opDelete are the original records and carry no sequence number; they
43	// remain readable forever so a directory written by an older version reopens
44	// unchanged. Records written by this version use the Seq variants instead:
45	// the value area is an 8-byte little-endian commit sequence number (unique
46	// and increasing per key) followed, for puts, by the actual value
47	// (valLen = 8 + len(value)). Sequence numbers let a pinning compaction merge
48	// versions from several eras into one history while keeping their order.
49	//
50	// A batch is one opBatchBegin marker (empty key, empty value), the Seq frames
51	// of its effective changes in list order, and one opBatchEnd marker (empty
52	// key, 8-byte value holding the number of inner frames). The markers frame
53	// the atomic commit: replay applies the inner frames only once the complete,
54	// intact end marker is seen, so a crash that leaves anything short of it
55	// discards the whole batch down to the begin offset. The whole frame group
56	// is buffered and forced with a single flush plus a single sync, so return
57	// from the append means the entire batch is stable.
58	const (
59		walName = "wal.log"
60		// compactTmpName holds a freshly built log during compaction; it is
61		// atomically renamed over wal.log and never observed directly. A file by
62		// this name left behind by a crash mid-compaction is stale and removed on
63		// the next open.
64		compactTmpName = "wal.log.compact"
65	
66		recordMagic  uint32 = 0x534e4150 // "SNAP"
67		opPut        byte   = 1
68		opDelete     byte   = 2
69		opMeta       byte   = 3
70		opPutSeq     byte   = 4
71		opDeleteSeq  byte   = 5
72		opBatchBegin byte   = 6
73		opBatchEnd   byte   = 7
74	
75		frameHeaderSize = 4 + 1 + 4 + 4
76		crcSize         = 4
77		metaValueSize   = 8
78		seqSize         = 8
79		maxRecord       = 1 << 30 // sanity bound on key and value lengths
80	)
81	
82	type walWriter struct {
83		f *os.File
84		w *bufio.Writer
85	
86		// syncs counts durable forces (flush + fsync pairs). Groups commit many
87		// batches per increment; it is read by tests while the store lock is
88		// held and otherwise carries no semantics.
89		syncs int
90	}
91	
92	func openWALWriter(dir string, replaySize int64) (*walWriter, error) {
93		f, err := os.OpenFile(dir+string(os.PathSeparator)+walName, os.O_RDWR|os.O_CREATE, 0o600)
94		if err != nil {
95			return nil, err
96		}
97		// Drop any torn tail that replay could not consume. A negative replaySize
98		// means the file is already exactly what should be on disk (e.g. a log
99		// just installed by compaction) and must not be truncated.
100		if replaySize >= 0 {
101			if err := f.Truncate(replaySize); err != nil {
102				f.Close()
103				return nil, err
104			}
105		}
106		if _, err := f.Seek(0, io.SeekEnd); err != nil {
107			f.Close()
108			return nil, err
109		}
110		return &walWriter{f: f, w: bufio.NewWriter(f)}, nil
111	}
112	
113	func (l *walWriter) writeFrame(op byte, key string, value []byte) error {
114		if err := l.encodeFrame(op, key, value); err != nil {
115			return err
116		}
117		if err := l.w.Flush(); err != nil {
118			return err
119		}
120		if err := l.f.Sync(); err != nil {
121			return err
122		}
123		l.syncs++
124		return nil
125	}
126	
127	// encodeFrame buffers one framed record. Used for ordinary appends (followed
128	// by a flush and sync) and while building a replacement log from scratch.
129	func (l *walWriter) encodeFrame(op byte, key string, value []byte) error {
130		hdr := make([]byte, frameHeaderSize)
131		binary.LittleEndian.PutUint32(hdr[0:4], recordMagic)
132		hdr[4] = op
133		binary.LittleEndian.PutUint32(hdr[5:9], uint32(len(key)))
134		binary.LittleEndian.PutUint32(hdr[9:13], uint32(len(value)))
135	
136		h := crc32.NewIEEE()
137		h.Write(hdr)
138		if _, err := l.w.Write(hdr); err != nil {
139			return err
140		}
141		if _, err := io.WriteString(l.w, key); err != nil {
142			return err
143		}
144		h.Write([]byte(key))
145		if len(value) > 0 {
146			if _, err := l.w.Write(value); err != nil {
147				return err
148			}
149			h.Write(value)
150		}
151		var crcb [crcSize]byte
152		binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
153		_, err := l.w.Write(crcb[:])
154		return err
155	}
156	
157	// encodeFrameSeq buffers a Seq record: seq's 8 bytes followed by value in
158	// the value area.
159	func (l *walWriter) encodeFrameSeq(op byte, key string, seq uint64, value []byte) error {
160		hdr := make([]byte, frameHeaderSize)
161		binary.LittleEndian.PutUint32(hdr[0:4], recordMagic)
162		hdr[4] = op
163		binary.LittleEndian.PutUint32(hdr[5:9], uint32(len(key)))
164		binary.LittleEndian.PutUint32(hdr[9:13], seqSize+uint32(len(value)))
165	
166		h := crc32.NewIEEE()
167		h.Write(hdr)
168		if _, err := l.w.Write(hdr); err != nil {
169			return err
170		}
171		if _, err := io.WriteString(l.w, key); err != nil {
172			return err
173		}
174		h.Write([]byte(key))
175		var seqb [seqSize]byte
176		binary.LittleEndian.PutUint64(seqb[:], seq)
177		if _, err := l.w.Write(seqb[:]); err != nil {
178			return err
179		}
180		h.Write(seqb[:])
181		if len(value) > 0 {
182			if _, err := l.w.Write(value); err != nil {
183				return err
184			}
185			h.Write(value)
186		}
187		var crcb [crcSize]byte
188		binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
189		_, err := l.w.Write(crcb[:])
190		return err
191	}
192	
193	// appendPut writes and durably commits one value record tagged with seq.
194	func (l *walWriter) appendPut(key string, value []byte, seq uint64) error {
195		if len(key) > maxRecord || seqSize+len(value) > maxRecord {
196			return fmt.Errorf("snapshot: record too large")
197		}
198		if err := l.encodeFrameSeq(opPutSeq, key, seq, value); err != nil {
199			return err
200		}
201		if err := l.w.Flush(); err != nil {
202			return err
203		}
204		if err := l.f.Sync(); err != nil {
205			return err
206		}
207		l.syncs++
208		return nil
209	}
210	
211	// appendDelete writes and durably commits one tombstone tagged with seq.
212	func (l *walWriter) appendDelete(key string, seq uint64) error {
213		if len(key) > maxRecord {
214			return fmt.Errorf("snapshot: record too large")
215		}
216		if err := l.encodeFrameSeq(opDeleteSeq, key, seq, nil); err != nil {
217			return err
218		}
219		if err := l.w.Flush(); err != nil {
220			return err
221		}
222		if err := l.f.Sync(); err != nil {
223			return err
224		}
225		l.syncs++
226		return nil
227	}
228	
229	// appendMeta durably records the cumulative snapshot count.
230	func (l *walWriter) appendMeta(snapshotCount uint64) error {
231		var v [metaValueSize]byte
232		binary.LittleEndian.PutUint64(v[:], snapshotCount)
233		return l.writeFrame(opMeta, "", v[:])
234	}
235	
236	// encodeBatch buffers one batch framed by begin/end markers, without
237	// flushing or syncing. Every change is a Seq record carrying its own commit
238	// sequence; end's value holds the inner-frame count. Several batches encoded
239	// back to back can be forced together with one flushSync, which is how
240	// concurrent commits share a single disk sync (group commit) while each
241	// batch stays a self-contained, independently recoverable framed commit.
242	func (l *walWriter) encodeBatch(changes []batchChange) error {
243		var endVal [metaValueSize]byte
244		binary.LittleEndian.PutUint64(endVal[:], uint64(len(changes)))
245		if err := l.encodeFrame(opBatchBegin, "", nil); err != nil {
246			return err
247		}
248		for i := range changes {
249			c := &changes[i]
250			var encErr error
251			if c.delete {
252				encErr = l.encodeFrameSeq(opDeleteSeq, c.key, c.seq, nil)
253			} else {
254				encErr = l.encodeFrameSeq(opPutSeq, c.key, c.seq, c.value)
255			}
256			if encErr != nil {
257				return encErr
258			}
259		}
260		return l.encodeFrame(opBatchEnd, "", endVal[:])
261	}
262	
263	// flushSync forces everything buffered so far to stable storage with one
264	// flush and one fsync.
265	func (l *walWriter) flushSync() error {
266		if err := l.w.Flush(); err != nil {
267			return err
268		}
269		if err := l.f.Sync(); err != nil {
270			return err
271		}
272		l.syncs++
273		return nil
274	}
275	
276	// position returns the current write offset (logical end of the log). It is
277	// only meaningful when no frames are buffered, as at the start of a group.
278	func (l *walWriter) position() (int64, error) {
279		return l.f.Seek(0, io.SeekEnd)
280	}
281	
282	// truncateTo rewinds the log to off, dropping anything a failed group
283	// buffered or auto-flushed past it, and re-arms the buffered writer.
284	func (l *walWriter) truncateTo(off int64) error {
285		l.w.Reset(l.f)
286		if err := l.f.Truncate(off); err != nil {
287			return err
288		}
289		_, err := l.f.Seek(off, io.SeekStart)
290		return err
291	}
292	
293	// appendBatch durably commits one standalone batch: encode and force with a
294	// single sync. Group leaders use encodeBatch plus flushSync directly so one
295	// sync can cover multiple batches.
296	func (l *walWriter) appendBatch(changes []batchChange) error {
297		if err := l.encodeBatch(changes); err != nil {
298			return err
299		}
300		return l.flushSync()
301	}
302	
303	func (l *walWriter) close() error { return l.f.Close() }
304	
305	// syncDirectory forces a directory entry change (such as a rename) to stable
306	// storage.
307	func syncDirectory(dir string) error {
308		d, err := os.Open(dir)
309		if err != nil {
310			return err
311		}
312		defer d.Close()
313		return d.Sync()
314	}
315	
316	// removeStaleCompact deletes a replacement log left behind by a compaction
317	// that crashed before its atomic rename. Its absence is not an error.
318	func removeStaleCompact(dir string) error {
319		err := os.Remove(dir + string(os.PathSeparator) + compactTmpName)
320		if err != nil && !errors.Is(err, os.ErrNotExist) {
321			return err
322		}
323		return nil
324	}
325	
326	// batchChange is one effective change in a batch commit.
327	type batchChange struct {
328		key    string
329		value  []byte // put payload; ignored when delete is true
330		seq    uint64
331		delete bool
332	}
333	
334	// buildCompactWAL writes the complete replacement log to compactTmpName and
335	// durably closes it, without touching wal.log or the live writer. It builds
336	// the complete replacement in compactTmpName and forces it to stable
337	// storage, so a crash at any point leaves either the old log untouched or a
338	// fully built temp that open-time cleanup discards.
339	func buildCompactWAL(dir string, histories []keyHistory, snapshotCount uint64) error {
340		if err := removeStaleCompact(dir); err != nil {
341			return err
342		}
343	
344		path := dir + string(os.PathSeparator)
345		tmp, err := os.OpenFile(path+compactTmpName, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
346		if err != nil {
347			return err
348		}
349		fail := func(err error) error {
350			tmp.Close()
351			os.Remove(path + compactTmpName)
352			return err
353		}
354		l := &walWriter{f: tmp, w: bufio.NewWriter(tmp)}
355		for i := range histories {
356			// Each key's retained versions are oldest-to-newest; replay prepends
357			// them in this order, so the last one becomes the head and every
358			// older one remains reachable down its chain. Frames are only
359			// buffered here; one flush plus one sync below commits the whole
360			// replacement atomically.
361			for _, ver := range histories[i].versions {
362				if ver.present {
363					if err := l.encodeFrameSeq(opPutSeq, histories[i].key, ver.seq, ver.value); err != nil {
364						return fail(err)
365					}
366				} else {
367					if err := l.encodeFrameSeq(opDeleteSeq, histories[i].key, ver.seq, nil); err != nil {
368						return fail(err)
369					}
370				}
371			}
372		}
373		// A zero count needs no record: replay of an absent meta yields 0. This
374		// keeps a trivially empty log empty rather than growing it.
375		if snapshotCount > 0 {
376			var v [metaValueSize]byte
377			binary.LittleEndian.PutUint64(v[:], snapshotCount)
378			if err := l.encodeFrame(opMeta, "", v[:]); err != nil {
379				return fail(err)
380			}
381		}
382		if err := l.w.Flush(); err != nil {
383			return fail(err)
384		}
385		if err := tmp.Sync(); err != nil {
386			return fail(err)
387		}
388		if err := tmp.Close(); err != nil {
389			os.Remove(path + compactTmpName)
390			return err
391		}
392		return nil
393	}
394	
395	// installCompactWAL atomically puts a previously built replacement log in
396	// place. The live writer must already have been closed by the caller:
397	// renaming over wal.log while a writer still holds it open fails on native
398	// filesystems that refuse a rename onto an open file, so releasing the old
399	// file first is what makes the swap succeed everywhere.
400	//
401	// renamed reports whether the rename landed. A crash between rename and the
402	// directory sync is still safe: on reopen wal.log is either the old or the
403	// complete new log, never a half-written file. When the rename fails the old
404	// log is intact and is reopened; the returned writer then points at it. When
405	// the rename landed but a writer cannot be opened on the new log, a nil
406	// writer is returned and the caller must treat the store as failed.
407	func installCompactWAL(dir string) (w *walWriter, renamed bool, err error) {
408		path := dir + string(os.PathSeparator)
409		if rerr := os.Rename(path+compactTmpName, path+walName); rerr != nil {
410			// The old log never moved; drop the staged temp so the directory is
411			// left with no intermediate state, then reopen the old log so
412			// committing can continue without needing a second compaction.
413			os.Remove(path + compactTmpName)
414			old, openErr := openWALWriter(dir, -1)
415			if openErr != nil {
416				return nil, false, errors.Join(rerr, openErr)
417			}
418			return old, false, rerr
419		}
420		// Make the rename durable; otherwise a crash could expose the old log
421		// even though the new one was fully written. The rename itself has
422		// already landed either way, so open and return the new writer so the
423		// caller adopts the now-linked file despite reporting the error.
424		syncErr := syncDirectory(dir)
425		next, openErr := openWALWriter(dir, -1)
426		if openErr != nil {
427			return nil, true, errors.Join(syncErr, openErr)
428		}
429		return next, true, syncErr
430	}
431	
432	// nodeVer is one retained version of a key.
433	type nodeVer struct {
434		seq     uint64
435		present bool // false marks a delete
436		value   []byte
437	}
438	
439	// keyHistory is the retained oldest-to-newest version chain for one key in a
440	// compacted log.
441	type keyHistory struct {
442		key      string
443		versions []nodeVer
444	}
445	
446	// readFullFrame reads one WAL frame from r. hdr is the reusable frame-header
447	// buffer. On a clean end of file it returns cleanEOF=true. Any torn read,
448	// unknown op, bad length or checksum mismatch returns n=0 with a nil error
449	// for an ordinary corrupt/torn frame (the caller ends the valid prefix
450	// before it) or a non-nil error only for an underlying read failure.
451	func readFullFrame(r *bufio.Reader, hdr []byte) (op byte, body []byte, frameLen int, cleanEOF bool, err error) {
452		if _, err := io.ReadFull(r, hdr); err != nil {
453			if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
454				// Exact end of log (EOF) or a partial header of a torn append
455				// (ErrUnexpectedEOF): either way the valid prefix ends here.
456				return 0, nil, 0, true, nil
457			}
458			return 0, nil, 0, false, err
459		}
460		magic := binary.LittleEndian.Uint32(hdr[0:4])
461		op = hdr[4]
462		keyLen := binary.LittleEndian.Uint32(hdr[5:9])
463		valLen := binary.LittleEndian.Uint32(hdr[9:13])
464		if magic != recordMagic ||
465			(op != opPut && op != opDelete && op != opMeta &&
466				op != opPutSeq && op != opDeleteSeq &&
467				op != opBatchBegin && op != opBatchEnd) ||
468			keyLen > maxRecord || valLen > maxRecord ||
469			(op == opDelete && valLen != 0) ||
470			(op == opPutSeq && valLen < seqSize) ||
471			(op == opDeleteSeq && valLen != seqSize) ||
472			(op == opMeta && (keyLen != 0 || valLen != metaValueSize)) ||
473			(op == opBatchBegin && (keyLen != 0 || valLen != 0)) ||
474			(op == opBatchEnd && (keyLen != 0 || valLen != metaValueSize)) {
475			return 0, nil, 0, false, nil // corrupt frame
476		}
477	
478		body = make([]byte, int(keyLen)+int(valLen))
479		if _, err := io.ReadFull(r, body); err != nil {
480			return 0, nil, 0, false, nil // torn body
481		}
482		var crcb [crcSize]byte
483		if _, err := io.ReadFull(r, crcb[:]); err != nil {
484			return 0, nil, 0, false, nil // torn checksum
485		}
486		h := crc32.NewIEEE()
487		h.Write(hdr)
488		h.Write(body)
489		if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() {
490			return 0, nil, 0, false, nil // checksum mismatch
491		}
492		return op, body, frameHeaderSize + len(body) + crcSize, false, nil
493	}
494	
495	// walSize reports the current size of wal.log, or 0 when it is absent.
496	func walFileSize(dir string) (int64, error) {
497		info, err := os.Stat(dir + string(os.PathSeparator) + walName)
498		if err != nil {
499			if errors.Is(err, os.ErrNotExist) {
500				return 0, nil
501			}
502			return 0, err
503		}
504		return info.Size(), nil
505	}
506	
507	// replayWAL applies every complete, intact record in commit order. kv
508	// records go to fn with their commit sequence (0 for legacy records that
509	// predate sequence numbers); meta records update snapshotCount. It returns
510	// the number of bytes occupied by the valid prefix; anything after it is a
511	// torn or corrupt tail discarded on the next open.
512	//
513	// Framed batches are applied atomically: their inner records are buffered
514	// until the intact end marker and only then handed to fn in list order. A
515	// torn or corrupt frame anywhere between begin and end (including a missing
516	// or count-mismatched end marker) makes the valid prefix end before the
517	// begin marker, so the whole batch disappears on reopen and no half-batch
518	// ever reaches the in-memory state.
519	func replayWAL(dir string, fn func(op byte, key string, value []byte, seq uint64)) (int64, uint64, error) {
520		f, err := os.Open(dir + string(os.PathSeparator) + walName)
521		if err != nil {
522			if errors.Is(err, os.ErrNotExist) {
523				return 0, 0, nil
524			}
525			return 0, 0, err
526		}
527		defer f.Close()
528		return replayFrames(f, 0, 0, fn)
529	}
530	
531	// replayWALTail is the checkpoint-reopen path: it seeds nothing itself (the
532	// caller has installed the checkpoint state) and replays only the frames at
533	// or after start, carrying initialSnap as the starting cumulative snapshot
534	// count. A missing WAL is reported as an empty tail ending exactly at start,
535	// which is the normal case for a checkpoint taken on an as-yet unwritten
536	// store.
537	func replayWALTail(dir string, start int64, initialSnap uint64, fn func(op byte, key string, value []byte, seq uint64)) (int64, uint64, error) {
538		f, err := os.Open(dir + string(os.PathSeparator) + walName)
539		if err != nil {
540			if errors.Is(err, os.ErrNotExist) {
541				return start, initialSnap, nil
542			}
543			return 0, 0, err
544		}
545		defer f.Close()
546		return replayFrames(f, start, initialSnap, fn)
547	}
548	
549	// replayFrames drives the same recovery as replayWAL but starts at byte
550	// offset start: a checkpoint reopen seeds memory from the checkpoint and
551	// only the WAL tail (frames at or after start) is replayed. start is an
552	// exact frame boundary — it was the writer's end-of-log position when the
553	// checkpoint was captured, and the capture happens under the same lock that
554	// forces each whole append — so the checkpoint-covered prefix is merely
555	// skipped, never parsed. initialSnap is the cumulative snapshot count
556	// already carried by the checkpoint (0 for a full replay); a meta frame in
557	// the tail assigns its absolute count as usual. The returned offset is the
558	// absolute end of the valid prefix, measured from the beginning of the file.
559	//
560	// A torn first frame at the cut is not an error but the normal case of a
561	// commit that crashed mid-append after the checkpoint: the frame never
562	// committed, so the valid prefix ends at the cut and the checkpoint already
563	// holds every state through it. Correct pairing of checkpoint and WAL is
564	// established structurally (compaction retires a checkpoint before it can
565	// rewrite the log), not by probing here.
566	func replayFrames(f *os.File, start int64, initialSnap uint64, fn func(op byte, key string, value []byte, seq uint64)) (int64, uint64, error) {
567		if _, err := f.Seek(start, io.SeekStart); err != nil {
568			return 0, 0, err
569		}
570		r := bufio.NewReader(f)
571		var offset int64 = start
572		snapshotCount := initialSnap
573		hdr := make([]byte, frameHeaderSize)
574	
575		// Batch framing state.
576		inBatch := false
577		batchStart := int64(0) // absolute offset of the batch's begin frame
578		var pending []replayedFrame
579	
580		// validPrefix reports where the file must be truncated to. A bad frame
581		// inside a batch invalidates from the batch's begin marker; outside a
582		// batch it invalidates only from that frame.
583		discard := func(at int64) (int64, uint64, error) {
584			if inBatch {
585				return batchStart, snapshotCount, nil
586			}
587			return at, snapshotCount, nil
588		}
589	
590		for {
591			at := offset
592			op, body, n, cleanEOF, rerr := readFullFrame(r, hdr)
593			if rerr != nil {
594				return 0, 0, rerr
595			}
596			if cleanEOF {
597				return discard(at) // absent/torn tail: valid prefix ends here
598			}
599			if n == 0 {
600				return discard(at) // corrupt or torn frame: prefix ends before it
601			}
602			offset += int64(n)
603	
604			keyLen := binary.LittleEndian.Uint32(hdr[5:9])
605			switch op {
606			case opBatchBegin:
607				if inBatch {
608					return batchStart, snapshotCount, nil // nested begin: corrupt batch
609				}
610				inBatch = true
611				batchStart = at
612				pending = pending[:0]
613			case opBatchEnd:
614				count := binary.LittleEndian.Uint64(body)
615				if !inBatch || count != uint64(len(pending)) {
616					// Stray end, or an end whose count does not match the
617					// buffered inner frames: the framed commit is not intact.
618					return discard(at)
619				}
620				for _, fr := range pending {
621					fn(fr.op, fr.key, fr.value, fr.seq)
622				}
623				pending = pending[:0]
624				inBatch = false
625			case opPut:
626				if inBatch {
627					return batchStart, snapshotCount, nil // only Seq frames may batch
628				}
629				fn(opPut, string(body[:keyLen]), body[keyLen:], 0)
630			case opDelete:
631				if inBatch {
632					return batchStart, snapshotCount, nil
633				}
634				fn(opDelete, string(body[:keyLen]), nil, 0)
635			case opPutSeq:
636				key := string(body[:keyLen])
637				seq := binary.LittleEndian.Uint64(body[keyLen : keyLen+seqSize])
638				value := body[keyLen+seqSize:]
639				if inBatch {
640					pending = append(pending, replayedFrame{opPutSeq, key, value, seq})
641				} else {
642					fn(opPutSeq, key, value, seq)
643				}
644			case opDeleteSeq:
645				key := string(body[:keyLen])
646				seq := binary.LittleEndian.Uint64(body[keyLen : keyLen+seqSize])
647				if inBatch {
648					pending = append(pending, replayedFrame{opDeleteSeq, key, nil, seq})
649				} else {
650					fn(opDeleteSeq, key, nil, seq)
651				}
652			case opMeta:
653				if inBatch {
654					return batchStart, snapshotCount, nil // meta may not ride inside a batch
655				}
656				snapshotCount = binary.LittleEndian.Uint64(body)
657			}
658		}
659	}
660	
661	// replayedFrame is one inner batch frame held during replay until its batch's
662	// end marker proves the commit is complete.
663	type replayedFrame struct {
664		op    byte
665		key   string
666		value []byte
667		seq   uint64
668	}
669

