43	// freshView builds the post-compaction in-memory view: one single-node head
44	// per currently present key; deleted keys drop out, as in the baseline.
45	func (p *compactionPlan) freshView() *view {
46		v := newView(nil)
47		for _, k := range p.keys {
48			versions := p.hist[k]
