58	// way the baseline did: every live present head, every cursor-pinned version,
59	// and the tombstone shielding a cursor-pinned older value; per-key versions
60	// ascending by sequence. pinned/keySeqs are produced by Compact under mu.
61	func buildCompactionPlan(pinned map[uint64]*node, keySeqs map[string][]uint64) *compactionPlan {
62		keys := make([]string, 0, len(keySeqs))
63		for k := range keySeqs {
64			keys = append(keys, k)
65		}
66		sort.Strings(keys)
67		hist := make(map[string][]nodeVer, len(keys))
