80	
81	// segmentFor returns the segment a frame with seq belongs to: 0 for frames at
82	// or before the first watermark, j for frames strictly after watermark j-1
83	// and at or before watermark j, and len(watermarks) for the post-window tail.
84	func segmentFor(seq uint64, watermarks []uint64) int {
85		for j, w := range watermarks {
86			if seq <= w {
87				return j
88			}
89		}
90		return len(watermarks)
91	}
