93	// segmentedWAL is the replacement WAL split at the surviving layer
94	// watermarks and the rebuilt layer metadata paired with its segments.
95	type segmentedWAL struct {
96		segments [][]keyHistory // len == len(watermarks)+1
97		cuts     []int64        // cut[j]: offset right after segment j; one per layer
98		layers   []rebuiltLayer
99		tailKeys []string
100	}
101	
102	// rebuiltLayer is one re-anchored layer's metadata; its cut is filled in once
103	// the segmented WAL is written.
104	type rebuiltLayer struct {
105		entries []checkpointEntry
106		seq     uint64
107		snaps   uint64
108	}
109	
110	// planSegmentedWAL partitions the frames the replacement WAL must carry at
111	// the surviving layers' sequence watermarks and derives, for each surviving
112	// layer, the entries its rebuilt file must carry — so that "seed layers
113	// 0..j, replay frames after cut j" reconstructs the identical terminal state
114	// a full replay of the new WAL does.
115	//
116	// windowLayers are the surviving (in-window) layers oldest first; only their
117	// sequence watermarks and snapshot counts are used. termStates[j] is the full
118	// terminal key state (puts and tombstones) at windowLayers[j]'s watermark,
119	// composed from the complete old chain; it is the authority for what each
120	// rebuilt layer must reproduce. The retained pin/head frames from plan are
121	// unioned with one terminal frame per key in each term state (deduped by
122	// sequence), so a version an in-window layer still shows is never shed even
123	// when the current view no longer needs it: keeping a layer usable must keep
124	// its state reconstructable. The extra versions are bounded by the window,
125	// not by cumulative commits.
126	func planSegmentedWAL(plan *compactionPlan, windowLayers []layerState, termStates [][]checkpointEntry, cur *view) *segmentedWAL {
127		n := len(windowLayers)
128		watermarks := make([]uint64, n)
129		snaps := make([]uint64, n)
130		for i, l := range windowLayers {
131			watermarks[i] = l.seq
132			snaps[i] = l.snaps
133		}
134	
135		// Collect the full required frame set per key, keyed by sequence so a
136		// version requested by several sources (pin, current head, layer state)
137		// is written exactly once.
138		type frame struct {
139			ver nodeVer
140		}
141		req := make(map[string]map[uint64]frame)
142		add := func(key string, ver nodeVer) {
143			m := req[key]
144			if m == nil {
