}

// OpenCursorPrefix opens a cursor over keys beginning with prefix.
func (s *Store) OpenCursorPrefix(prefix string) (*Cursor, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed.Load() {
		return nil, errStoreClosed
	}
