// compaction. Close is idempotent, serializes with concurrent pages and
// other closes, and always returns nil; reads after Close are empty results
// without error.
func (c *Cursor) Close() error {
	c.mu.Lock()
	already := c.closed
	c.closed = true
	st := c.store
	c.store = nil
	c.mu.Unlock()

	if already || st == nil {
		return nil
	}
	st.unregisterCursor(c)
	return nil
}

