func TestRestoreTargetValidation(t *testing.T) {
	base := t.TempDir()
	s := populateStore(t, filepath.Join(base, "store"))
	defer s.Close()
	if err := s.Backup(filepath.Join(base, "backup")); err != nil {
		t.Fatal(err)
